from typing import List

def count_colors_with_one_between(n: int, A: List[int]) -> int:
    count = 0

    for i in range(1, n + 1):
        indices = [index for index, value in enumerate(A) if value == i]
        if len(indices) == 2 and indices[1] - indices[0] == 2:
            count += 1

    return count
